SourceCode.Declaration:
/// <summary>
/// Stock count control center: New hazard count (user, 13 Nov: hazard counts can also start in
/// D365FO, not only from the outside system's request). Makes the same Hazard record that
/// HSMobileOpsCountRequestService.createHazardCount makes - warehouse, reference, due time - and
/// the items to count are then added on the Requested items tab. No journal until Create journal.
/// </summary>
class HSMobileOpsCountNewHazard
{
}

Method.Source:
public static void main(Args _args)
{
    Dialog                 dialog = new Dialog('New hazard count');
    DialogField            warehouseField = dialog.addField(extendedTypeStr(InventLocationId), 'Warehouse');
    DialogField            referenceField = dialog.addField(extendedTypeStr(Description), 'Reference', 'The recall or request this count is for. Optional; a reference can have only one hazard count that is not cancelled.');
    DialogField            dueField = dialog.addField(extendedTypeStr(TransDateTime), 'Due', 'When the count must be done. Optional.');
    DialogField            descriptionField = dialog.addField(extendedTypeStr(Description), 'Description');
    HSMobileOpsCountMaster master;
    HSMobileOpsCountMaster existing;
    InventLocationId       warehouse;
    str                    reference;

    if (!dialog.run())
    {
        return;
    }
    warehouse = warehouseField.value();
    if (!InventLocation::find(warehouse).RecId)
    {
        throw error(strFmt('Warehouse %1 does not exist.', warehouse));
    }
    reference = strLTrim(strRTrim(referenceField.value()));
    if (reference)
    {
        // As the outside system's request: one open hazard count per reference.
        select firstonly MasterId from existing
            where existing.MasterType  == HSMobileOpsCountMasterType::Hazard
               && existing.ExternalRef == reference
               && existing.Status      != HSMobileOpsCountMasterStatus::Cancelled;
        if (existing.MasterId)
        {
            throw error(strFmt('Reference %1 already has hazard count %2.', reference, existing.MasterId));
        }
    }
    ttsbegin;
    master = HSMobileOpsCountControl::newMaster(HSMobileOpsCountMasterType::Hazard, warehouse,
        descriptionField.value() ? descriptionField.value() : (reference ? strFmt('Hazard count %1', reference) : strFmt('Hazard count %1', warehouse)),
        curUserId(), reference, dueField.value());
    ttscommit;
    info(strFmt('%1 created. Add the items to count on the Requested items tab - the handhelds in %2 see it once it has some.',
        master.MasterId, warehouse));
    if (_args && _args.caller() is FormRun)
    {
        FormRun callerForm = _args.caller() as FormRun;
        int     i;
        for (i = 1; i <= callerForm.dataSourceCount(); i++)
        {
            callerForm.dataSource(i).research(true);
        }
    }
}
